css:
/* ARENA RESERVER SECTIONS v6 (reconstruit le 05/11/2026) */
.arena-resa-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:56px}
@media(max-width:1024px){.arena-resa-cards{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.arena-resa-cards{grid-template-columns:1fr!important}}
.arena-resa-card{padding:22px 22px}
.arena-resa-card p a{color:#189979;text-decoration:none;border-bottom:1px solid #AAD7CC}
.arena-resa__season{margin:10px 0 0;position:relative;z-index:3;text-align:center;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#6F8A86}
.arena-resa-h2{margin:10px 0 18px;font-family:"Tenor Sans",sans-serif;font-weight:400;font-size:clamp(24px,2.6vw,32px);line-height:1.2;letter-spacing:.02em;color:#204848}
.arena-rooms{margin-top:56px}
.arena-rooms__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:26px}
.arena-room{display:block;position:relative;border-radius:22px;overflow:hidden;box-shadow:0 14px 36px rgba(32,72,72,.10);text-decoration:none;background:#14201C;aspect-ratio:3/4}
.arena-room img{display:block;width:100%;height:100%;object-fit:cover;transition:transform 1.2s ease}
.arena-room:hover img{transform:scale(1.04)}
.arena-room__b{position:absolute;left:0;right:0;bottom:0;padding:70px 22px 22px;background:linear-gradient(180deg,rgba(20,32,28,0),rgba(20,32,28,.8));color:#F4F1EA}
.arena-room__n{display:block;font-family:"Tenor Sans",sans-serif;font-size:22px;letter-spacing:.04em;line-height:1.2;color:#F4F1EA}
.arena-room__d{display:block;margin-top:6px;font-size:13px;line-height:1.5;color:rgba(244,241,234,.8)}
.arena-room__p{display:block;margin-top:10px;font-size:11.5px;letter-spacing:.18em;text-transform:uppercase;color:#AAD7CC}
.arena-rooms__more{margin:24px 0 0;text-align:center}
.arena-rooms__more a{font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:#189979;text-decoration:none;border-bottom:1px solid #AAD7CC;padding-bottom:3px}
.arena-resa-photo{margin:56px 0 0;border-radius:22px;overflow:hidden;box-shadow:0 18px 44px rgba(32,72,72,.14)}
.arena-resa-photo img{display:block;width:100%;height:auto;aspect-ratio:2/1;object-fit:cover}
.arena-resa-about{display:grid;grid-template-columns:1.15fr .85fr;gap:40px;margin-top:56px;align-items:start}
.arena-resa-about__text p{font-size:15.5px;line-height:1.75;color:#2F4A46;margin:0 0 14px}
.arena-marks{list-style:none;margin:26px 0 0;padding:0;border-top:1px solid #DBE4CA}
.arena-marks li{display:grid;grid-template-columns:150px 1fr;gap:16px;padding:12px 0;border-bottom:1px solid #DBE4CA;font-size:14.5px;line-height:1.5;color:#2F4A46}
.arena-marks__k{font-family:"Tenor Sans",sans-serif;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#436161;padding-top:3px}
.arena-reviews{background:#F4F6F0;border-radius:22px;padding:28px 28px 22px}
.arena-review{margin:0 0 18px;padding:0 0 18px;border-bottom:1px solid #DBE4CA}
.arena-review:last-of-type{border-bottom:0;margin-bottom:6px}
.arena-review__stars{display:block;color:#C9B37A;letter-spacing:.2em;font-size:13px;margin-bottom:8px}
.arena-review p{margin:0 0 8px;font-size:14.5px;line-height:1.65;color:#2F4A46}
.arena-review cite{font-style:normal;font-family:"Tenor Sans",sans-serif;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#436161}
.arena-reviews__src{margin:0;font-size:12px;letter-spacing:.06em;color:#6F8A86}
.arena-reviews__src a{color:#189979;text-decoration:none;border-bottom:1px solid #AAD7CC}
.arena-faq{margin-top:56px;max-width:860px}
.arena-faq__item{border-top:1px solid #DBE4CA;padding:4px 0}
.arena-faq__item:last-of-type{border-bottom:1px solid #DBE4CA}
.arena-faq__item summary{cursor:pointer;list-style:none;padding:16px 36px 16px 0;position:relative;font-family:"Tenor Sans",sans-serif;font-size:18px;letter-spacing:.02em;color:#204848}
.arena-faq__item summary::-webkit-details-marker{display:none}
.arena-faq__item summary::after{content:"+";position:absolute;right:6px;top:12px;font-size:24px;line-height:1;color:#189979;transition:transform .3s}
.arena-faq__item[open] summary::after{transform:rotate(45deg)}
.arena-faq__item p{margin:0 0 18px;font-size:15px;line-height:1.75;color:#2F4A46;max-width:760px}
.arena-resa-contact{margin-top:56px}
@media(max-width:900px){.arena-resa-about{grid-template-columns:1fr;gap:28px}}
@media(max-width:767px){.arena-rooms{margin-top:40px}.arena-rooms__grid{grid-template-columns:1fr;gap:16px}.arena-room{aspect-ratio:4/3}.arena-room__b{padding:50px 20px 18px}.arena-resa-photo{margin-top:40px}.arena-resa-photo img{aspect-ratio:4/3}.arena-resa-about,.arena-faq,.arena-resa-contact{margin-top:40px}.arena-marks li{grid-template-columns:1fr;gap:4px}.arena-reviews{padding:22px 20px 16px}}
